unmarkedConfigVal, _ := configVal.UnmarkDeep()
unmarkedBefore, beforePaths := change.Before.UnmarkDeepWithPaths()
unmarkedAfter, afterPaths := change.After.UnmarkDeepWithPaths()

// If we have an Update action, our before and after values are equal,
// and only differ on their sensitivity, the newVal is the after val
// and we should not communicate with the provider. We do need to update
// the state with this new value, to ensure the sensitivity change is
// persisted.
eqV := unmarkedBefore.Equals(unmarkedAfter)
eq := eqV.IsKnown() && eqV.True()
if change.Action == plans.Update && eq {
	marksDiffer := false
	if len(beforePaths) != len(afterPaths) {
		marksDiffer = true
	} else if len(beforePaths) > 0 {
		lessMarks := func(s []cty.PathValueMarks) func(i, j int) bool {
			return func(i, j int) bool {
				// the sort only needs to be consistent, so use the GoString format
				// to get a comparable value
				return fmt.Sprintf("%#v", s[i]) < fmt.Sprintf("%#v", s[j])
			}
		}
		sort.Slice(beforePaths, lessMarks(beforePaths))
		sort.Slice(afterPaths, lessMarks(afterPaths))
		for i := 0; i < len(beforePaths); i++ {
			leftMark := beforePaths[i]
			rightMark := afterPaths[i]
			if !leftMark.Marks.Equal(rightMark.Marks) {
				marksDiffer = true
			} else {
				leftPath := leftMark.Path
				rightPath := rightMark.Path
				pathLen := len(leftPath)
				if len(rightPath) != pathLen {
					marksDiffer = true
					if len(rightPath) < pathLen {
						pathLen = len(rightPath)
					}
				}
				for stepIdx := 0; stepIdx < pathLen; stepIdx++ {
					switch leftStep := leftPath[stepIdx].(type) {
					case cty.GetAttrStep:
						rightStep, ok := rightPath[stepIdx].(cty.GetAttrStep)
						if !ok || leftStep.Name != rightStep.Name {
							marksDiffer = true
						}
					case cty.IndexStep:
						rightStep, ok := rightPath[stepIdx].(cty.IndexStep)
						if !ok || !leftStep.Key.RawEquals(rightStep.Key) {
							marksDiffer = true
						}
					default:
						marksDiffer = true
					}
					if marksDiffer {
						break
					}
				}
			}
			if marksDiffer {
				break
			}
		}
	}
	if marksDiffer {
		// Copy the previous state, changing only the value
		newState := &states.ResourceInstanceObject{
			CreateBeforeDestroy: state.CreateBeforeDestroy,
			Dependencies:        state.Dependencies,
			Private:             state.Private,
			Status:              state.Status,
			Value:               change.After,
		}
		return newState, diags
	}
}

